"use client";

import { loadFont as loadFigtree } from "@remotion/google-fonts/Figtree";
import { loadFont as loadSerif } from "@remotion/google-fonts/InstrumentSerif";
import type React from "react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  AbsoluteFill,
  continueRender,
  delayRender,
  Easing,
  Img,
  interpolate,
  spring,
  staticFile,
} from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import type { GradientParams } from "@/lib/remocn/gsh/gradient-engine";
import { GshGround, gshParams } from "@/lib/remocn/gsh/gsh-ground";
import type { GshPresetId } from "@/lib/remocn/gsh/presets";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  BEAT,
  DEFAULT_FIRST_STEP,
  DEFAULT_TEXT,
  hopTimes,
  type PhotoCaretElementId,
  parseLines,
  photoCaretTimeline,
} from "./timeline";

const figtree = loadFigtree("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const serif = loadSerif("italic", { weights: ["400"], subsets: ["latin"] });

export interface PhotoCaretProps {
  text?: string;
  accentWord?: string;
  src?: string;
  images?: string[];
  accent?: string;
  ink?: string;
  /** Solid fill in place of the gradient ground; "transparent" drops it. */
  background?: string;
  /** Typeface for the copy. Load it yourself; Figtree by default. */
  fontFamily?: string;
  /** Italic typeface for the accent word. Load it yourself; Instrument Serif by default. */
  accentFont?: string;
  theme?: "dark" | "light";
  ground?: GshPresetId;
  groundParams?: Partial<GradientParams>;
  firstStep?: number;
  /** Frames on the finished line after the accent word lands; the slow push runs through it. */
  hold?: number;
  /** Size of the copy and photos, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  /**
   * Moves, trims or stretches the tile's intro, single hops, the push and
   * the photos, by the ids in `./timeline`. Frames on the scene timeline,
   * after `delay` and `speed`.
   */
  timing?: Timing<PhotoCaretElementId>;
}

const LIGHT_GROUND: Partial<GradientParams> = {
  kind: "mist",
  background: "#ecebe8",
  colors: ["#ffffff", "#f7f6f3", "#dcdcdf", "#c4c6cf"],
  blur: 0.8,
  warp: 0.3,
  seed: 4,
  grain: 0.16,
};

const THEMES = {
  dark: {
    ink: "#f4f2ee",
    accent: "#a3b2ff",
    ground: "riptide" as GshPresetId | undefined,
    groundParams: undefined as Partial<GradientParams> | undefined,
    groundOffset: 5,
    scrim: "4,5,12",
    scrimAlpha: 0.55,
    border: "rgba(255,255,255,0.16)",
    shadow:
      "0 1px 2px rgba(1,2,8,0.45), 0 10px 24px rgba(1,2,8,0.45), 0 36px 72px rgba(1,2,8,0.5)",
  },
  light: {
    ink: "#151515",
    accent: "#3B5BFD",
    ground: undefined as GshPresetId | undefined,
    groundParams: LIGHT_GROUND as Partial<GradientParams> | undefined,
    groundOffset: 2,
    scrim: "240,239,236",
    scrimAlpha: 0.5,
    border: "rgba(20,20,24,0.08)",
    shadow:
      "0 1px 2px rgba(30,30,40,0.12), 0 8px 20px rgba(30,30,40,0.12), 0 28px 56px rgba(30,30,40,0.14)",
  },
};

const DEFAULT_IMAGES = [
  "templates/brand-guidelines/chair.jpg",
  "templates/product-showcase/sculpture.jpg",
  "templates/launch-anything/desk.jpg",
  "templates/brand-guidelines/materials.jpg",
  "templates/product-showcase/courtyard.jpg",
  "templates/product-showcase/gallery.jpg",
  "reel/reel-4.jpg",
];

const FONT_PX = 200;
const TRACK = -0.03;
const SERIF_SCALE = 1.14;
const LH = 1.08;
const TILE_H = 1.15;
const TILE_W = 0.86;
const STAGGER = [0.62, 0, 1];
const TYPE_IN = Easing.bezier(0.32, 0.72, 0, 1);
const PUSH = Easing.bezier(0.87, 0, 0.13, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const CAMERA = { mass: 1, damping: 26, stiffness: 120 };
const CARD = { mass: 0.8, damping: 18, stiffness: 160 };
const CHIP = { mass: 0.5, damping: 12, stiffness: 200 };

interface Metrics {
  width: (s: string, accent: boolean) => number;
  cap: number;
}

function buildMetrics(
  _version: number,
  sansFamily: string,
  serifFamily: string,
): Metrics {
  const ctx = document.createElement("canvas").getContext("2d");
  const sansFont = `400 ${FONT_PX}px "${sansFamily}"`;
  const serifFont = `italic 400 ${FONT_PX * SERIF_SCALE}px "${serifFamily}"`;
  const cache: Record<string, number> = {};
  let cap = 0.7;
  if (ctx) {
    ctx.font = sansFont;
    const box = ctx.measureText("H").actualBoundingBoxAscent / FONT_PX;
    if (box > 0.3) cap = box;
  }
  return {
    width: (s: string, accent: boolean) => {
      const k = `${accent ? 1 : 0}${s}`;
      if (cache[k] === undefined) {
        if (!ctx) return s.length * 0.52;
        ctx.font = accent ? serifFont : sansFont;
        const track = accent ? 0 : TRACK * Array.from(s).length;
        cache[k] = ctx.measureText(s).width / FONT_PX + track;
      }
      return cache[k];
    },
    cap,
  };
}

function useMetrics(sansFamily: string, serifFamily: string) {
  const [version, setVersion] = useState(0);
  const [handle] = useState(() => delayRender("photo-caret: measuring"));
  const released = useRef(false);
  useEffect(() => {
    let live = true;
    const bump = () => {
      if (live) setVersion((v) => v + 1);
    };
    document.fonts.addEventListener("loadingdone", bump);
    Promise.all([
      figtree.waitUntilDone(),
      serif.waitUntilDone(),
      document.fonts.load(`400 ${FONT_PX}px "${sansFamily}"`),
      document.fonts.load(`italic 400 ${FONT_PX}px "${serifFamily}"`),
    ])
      .catch(() => undefined)
      .then(() => {
        bump();
        if (!released.current) {
          released.current = true;
          continueRender(handle);
        }
      });
    return () => {
      live = false;
      document.fonts.removeEventListener("loadingdone", bump);
    };
  }, [handle, sansFamily, serifFamily]);
  return useMemo(
    () => buildMetrics(version, sansFamily, serifFamily),
    [version, sansFamily, serifFamily],
  );
}

export const photoCaretLength = (
  text = DEFAULT_TEXT,
  firstStep = DEFAULT_FIRST_STEP,
  hold = BEAT.hold,
) => {
  const n = parseLines(text).flat().length;
  const hops = hopTimes(n, firstStep);
  return hops[hops.length - 1] + BEAT.settle + hold;
};

type Sat = { x: number; y: number; s: number; far: boolean; r: number };

const SATS_WIDE: Sat[] = [
  { x: 0.065, y: 0.22, s: 0.17, far: false, r: -3 },
  { x: 0.27, y: 0.87, s: 0.16, far: false, r: 2 },
  { x: 0.92, y: 0.64, s: 0.2, far: false, r: 3 },
  { x: 0.42, y: 0.06, s: 0.17, far: true, r: 0 },
  { x: 0.74, y: 0.95, s: 0.18, far: true, r: 0 },
  { x: 0.04, y: 0.66, s: 0.2, far: true, r: 0 },
  { x: 0.96, y: 0.18, s: 0.18, far: true, r: 0 },
];

const SATS_TALL: Sat[] = [
  { x: 0.2, y: 0.17, s: 0.15, far: false, r: -3 },
  { x: 0.78, y: 0.8, s: 0.17, far: false, r: 3 },
  { x: 0.24, y: 0.86, s: 0.12, far: false, r: 2 },
  { x: 0.66, y: 0.08, s: 0.12, far: true, r: 0 },
  { x: 0.92, y: 0.26, s: 0.12, far: true, r: 0 },
  { x: 0.06, y: 0.7, s: 0.12, far: true, r: 0 },
  { x: 0.56, y: 0.95, s: 0.11, far: true, r: 0 },
];

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function PhotoCaret(props: PhotoCaretProps) {
  const {
    text = DEFAULT_TEXT,
    accentWord = "it.",
    src,
    images,
    accent,
    ink,
    background,
    fontFamily = figtree.fontFamily,
    accentFont = serif.fontFamily,
    theme = "dark",
    ground,
    groundParams,
    scale: layerScale = 1,
    delay = 0,
    speed = 1,
    timing,
  } = props;
  const frame = Math.max(0, useSceneFrame() - delay) * speed;
  const glide = useGlide();
  const { width: W, height: H, fps, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    photoCaretTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const c = THEMES[theme];
  const inkC = ink ?? c.ink;
  const hi = accent ?? c.accent;
  const preset = ground ?? (groundParams ? undefined : c.ground);
  const gParams = groundParams ?? (ground ? undefined : c.groundParams);
  const bg = gshParams(preset, gParams).background;
  const portrait = H > W * 1.1;
  const m = useMetrics(fontFamily, accentFont);
  const tileSrc = src ?? staticFile("templates/brand-guidelines/ceramics.jpg");
  const satSrc = (images ?? DEFAULT_IMAGES.map((p) => staticFile(p))).filter(
    Boolean,
  );

  const lines = useMemo(() => parseLines(text), [text]);

  const layout = useMemo(() => {
    const space = m.width(" ", false) + 0.02;
    const rows = lines.map((ws) => {
      const widths = ws.map((w) => m.width(w, w === accentWord));
      const total = widths.reduce((a, b) => a + b, 0) + space * (ws.length - 1);
      return { ws, widths, total };
    });
    const maxW = Math.max(...rows.map((r) => r.total));
    const parkGap = 0.24;
    const spanW = portrait ? maxW : maxW + parkGap + TILE_W;
    const spanH = rows.length * LH + (portrait ? TILE_H + 0.5 : 0.3);
    const F = portrait
      ? Math.min((W * 0.84) / spanW, (H * 0.42) / spanH)
      : Math.min((W * 0.7) / spanW, (H * 0.68) / spanH);
    const cap = m.cap * F;
    const words: {
      text: string;
      accent: boolean;
      x: number;
      w: number;
      base: number;
      line: number;
    }[] = [];
    rows.forEach((r, li) => {
      const ox = (maxW - r.total) * STAGGER[li % STAGGER.length] * F;
      let x = ox;
      r.ws.forEach((w, wi) => {
        words.push({
          text: w,
          accent: w === accentWord,
          x,
          w: r.widths[wi] * F,
          base: li * LH * F,
          line: li,
        });
        x += (r.widths[wi] + space) * F;
      });
    });
    const tw = TILE_W * F;
    const th = TILE_H * F;
    const slotY = (base: number) => base - cap * 0.42 - th / 2;
    const slots = words.map((w) => ({ x: w.x, y: slotY(w.base) }));
    const park = portrait
      ? { x: maxW * F - tw, y: -cap - 0.34 * F - th }
      : { x: maxW * F + parkGap * F, y: slotY(0) - cap * 0.35 };
    slots.push(park);
    const minY = Math.min(park.y, -cap - 0.04 * F);
    const maxY = (rows.length - 1) * LH * F + 0.06 * F;
    const right = Math.max(maxW * F, park.x + tw);
    const cx = right / 2;
    const cy = (minY + maxY) / 2;
    return {
      F,
      cap,
      tw,
      th,
      cx,
      cy,
      words,
      slots,
      bbox: { x0: 0, x1: right, y0: minY, y1: maxY },
    };
  }, [m, lines, accentWord, portrait, W, H]);

  const { F, cap, tw, th, words, slots } = layout;
  const n = words.length;
  const hopEls = useMemo(
    () => Array.from({ length: n }, (_, k) => tl.get(`word:${k}`)),
    [tl, n],
  );
  const hops = hopEls.map((e) => e.start);
  const payoff = hops[n - 1];
  const payoffEl = hopEls[n - 1];
  const pushEl = tl.get("push");
  const introEl = tl.get("intro");

  const states = useMemo(() => {
    const out: { cx: number; cy: number; s: number }[] = [];
    for (let k = 0; k <= n; k++) {
      let x0 = slots[k].x;
      let x1 = slots[k].x + tw;
      let y0 = slots[k].y;
      let y1 = slots[k].y + th;
      for (let i = 0; i < k; i++) {
        x0 = Math.min(x0, words[i].x);
        x1 = Math.max(x1, words[i].x + words[i].w);
        y0 = Math.min(y0, words[i].base - cap);
        y1 = Math.max(y1, words[i].base + 0.1 * F);
      }
      const bw = x1 - x0;
      const bh = y1 - y0;
      const fit = Math.min(
        (W * (portrait ? 0.84 : 0.7)) / bw,
        (H * (portrait ? 0.42 : 0.68)) / bh,
      );
      const s = k === n ? 1 : Math.min(portrait ? 1.08 : 1.2, Math.max(1, fit));
      const w = k === n ? 1 : 0.85;
      out.push({
        cx: layout.cx + ((x0 + x1) / 2 - layout.cx) * w,
        cy: layout.cy + ((y0 + y1) / 2 - layout.cy) * w,
        s,
      });
    }
    return out;
  }, [n, slots, tw, th, words, cap, F, W, H, portrait, layout]);

  const camAt = (t: number) => {
    let cx = states[0].cx;
    let cy = states[0].cy;
    let ls = Math.log(states[0].s);
    for (let k = 0; k < n; k++) {
      const p = spring({
        frame: t - hops[k],
        fps,
        config: CAMERA,
      });
      cx += (states[k + 1].cx - states[k].cx) * p;
      cy += (states[k + 1].cy - states[k].cy) * p;
      ls += (Math.log(states[k + 1].s) - Math.log(states[k].s)) * p;
    }
    return { cx, cy, s: Math.exp(ls) };
  };
  const pushAt = (t: number) =>
    1 +
    0.03 *
      interpolate(t, [pushEl.start, pushEl.end], [0, 1], {
        ...CLAMP,
        easing: PUSH,
      });
  const viewAt = (t: number) => {
    const c = camAt(t);
    const s = c.s * pushAt(t);
    return { s, ox: W / 2 - c.cx * s, oy: H / 2 - c.cy * s };
  };
  const push = pushAt(frame);
  const { s: scale, ox, oy } = viewAt(frame);
  // Chrome parks a glyph raster on a whole pixel vertically for as long as the
  // matrix is axis-aligned, so the words click along under the camera. The
  // drawing is marked so they lean off that grid while it moves. The camera's
  // springs have long tails, so this compares neighbouring frames, scale
  // weighed at the frame's width.
  const viewDelta = (a: number, b: number) => {
    const p = viewAt(a);
    const q = viewAt(b);
    return Math.max(
      Math.abs(p.ox - q.ox),
      Math.abs(p.oy - q.oy),
      Math.abs(p.s - q.s) * W,
    );
  };
  const camMoving =
    viewDelta(frame + 1, frame) > 1e-3 || viewDelta(frame, frame - 1) > 1e-3;

  const tileAt = (fr: number) => {
    let tx = slots[0].x;
    let ty = slots[0].y;
    let squash = 0;
    let lead = 0;
    for (let k = 0; k < n; k++) {
      const f = fr - hops[k];
      if (f < 0) break;
      const p = spring({ frame: f, fps, config: CARD });
      const a = slots[k];
      const b = slots[k + 1];
      const sameLine = k < n - 1 && words[k].line === words[k + 1].line;
      const lift = sameLine ? 0.16 * F : 0.06 * F;
      tx = a.x + (b.x - a.x) * p;
      ty = a.y + (b.y - a.y) * p - lift * Math.sin(Math.PI * Math.min(1, p));
      const pPrev = spring({ frame: f - 1, fps, config: CARD });
      lead = Math.max(
        lead,
        Math.abs(p - pPrev) * Math.hypot(b.x - a.x, b.y - a.y),
      );
      squash = interpolate(
        f,
        [0, hopEls[k].beat("squashPeak"), hopEls[k].beat("squash")],
        [0, 1, 0],
        CLAMP,
      );
    }

    const intro = spring({
      frame: fr - introEl.start,
      fps,
      config: CAMERA,
      durationInFrames: introEl.length,
    });
    const view = viewAt(fr);
    const sx = view.ox + tx * view.s;
    const sy = view.oy + ty * view.s;
    const sw = tw * view.s;
    const sh = th * view.s;
    return {
      tx,
      squash,
      lead,
      intro,
      tileW: bigW + (sw - bigW) * intro,
      tileH: bigH + (sh - bigH) * intro,
      tileX: bigX + (sx - bigX) * intro,
      tileY: bigY + (sy - bigY) * intro,
    };
  };
  const bigH = H * (portrait ? 0.36 : 0.56);
  const bigW = bigH * 0.78;
  const bigX = W / 2 - bigW / 2;
  const bigY = H / 2 - bigH / 2;
  const { tx, squash, lead, intro, tileW, tileH, tileX, tileY } = tileAt(frame);
  // Layout rounds a box's edges to whole pixels, so the tile hopping by
  // `left`/`top` steps unevenly; while it travels, it is placed by a
  // transform instead. Under 1/64px a frame, layout's own grid, it keeps the
  // plain layout, so its resting frames are untouched.
  const tileTravels = [frame - 1, frame + 1].some((fr) => {
    const o = tileAt(fr);
    return (
      Math.abs(o.tileX - tileX) > 1 / 64 || Math.abs(o.tileY - tileY) > 1 / 64
    );
  });
  const introBlur = Math.abs(
    intro -
      spring({
        frame: frame - 1 - introEl.start,
        fps,
        config: CAMERA,
        durationInFrames: introEl.length,
      }),
  );
  const moveBlur = Math.min(8, lead * scale * 0.09 + introBlur * 40);
  const tileScale = 1 + 0.04 * squash;

  const hopProgressRight = tx + tw;
  const accentHit = interpolate(
    frame,
    [payoff, payoff + payoffEl.beat("accent")],
    [0, 1],
    {
      ...CLAMP,
      easing: TYPE_IN,
    },
  );

  const sats = portrait ? SATS_TALL : SATS_WIDE;
  const satStart = (i: number, far: boolean) =>
    tl.get(far ? `far:${i}` : `near:${i}`).start;

  // A word rising into place by its `y` attribute clicks the same way.
  const wordRising = words.some((_, i) => {
    const f = frame - hops[i];
    return f > -1 && f < hopEls[i].beat("reveal") + 1;
  });
  // The camera holds the words under a scale, off the pixel grid, where
  // dropping the lean would snap them to the nearest pixel. A drawing in SVG
  // leans only while its mark says it moves, so it says so there too.
  const camOffGrid = Math.abs(scale - 1) > 1e-6;
  const textTilt = camMoving || wordRising || camOffGrid;

  const renderWord = (w: (typeof words)[number], i: number) => {
    const start = hops[i];
    const f = frame - start;
    if (f < 0) return null;
    const timeP = interpolate(f, [0, hopEls[i].beat("reveal")], [0, 1], {
      ...CLAMP,
      easing: TYPE_IN,
    });
    const sweep = i < n - 1 ? hopProgressRight - w.x : 0;
    const reveal = Math.min(w.w + 0.2 * F, Math.max(sweep, w.w * timeP * 1.04));
    const rise = (1 - timeP) * 0.06 * F;
    const blur = (1 - timeP) * 5;
    const color = w.accent
      ? accentHit >= 1
        ? hi
        : `color-mix(in oklab, ${hi} ${accentHit * 100}%, ${inkC})`
      : inkC;
    const clipId = `pc-clip-${i}`;
    const filtId = `pc-blur-${i}`;
    return (
      <g key={`${w.text}-${i}`}>
        <defs>
          <clipPath id={clipId}>
            <rect
              x={w.x - 0.1 * F}
              y={w.base - 1.3 * F}
              width={reveal + 0.1 * F}
              height={1.7 * F}
            />
          </clipPath>
          {blur > 0.1 ? (
            <filter id={filtId} x="-20%" y="-50%" width="140%" height="200%">
              <feGaussianBlur stdDeviation={`${blur / scale} 0`} />
            </filter>
          ) : null}
        </defs>
        <g clipPath={`url(#${clipId})`}>
          <text
            x={w.x}
            y={w.base + rise}
            fill={color}
            filter={blur > 0.1 ? `url(#${filtId})` : undefined}
            fontFamily={w.accent ? accentFont : fontFamily}
            fontStyle={w.accent ? "italic" : "normal"}
            fontWeight={400}
            fontSize={w.accent ? F * SERIF_SCALE : F}
            letterSpacing={w.accent ? "0em" : `${TRACK}em`}
            opacity={interpolate(f, [0, hopEls[i].beat("fade")], [0, 1], CLAMP)}
            style={{ fontKerning: "normal" }}
          >
            {w.text}
          </text>
        </g>
      </g>
    );
  };

  const renderSat = (st: Sat, i: number, layer: "far" | "near") => {
    if ((layer === "far") !== st.far) return null;
    const img = satSrc[(i + 1) % Math.max(1, satSrc.length)];
    if (!img) return null;
    const start = satStart(
      sats.filter((q) => q.far === st.far).indexOf(st),
      st.far,
    );
    const p = spring({ frame: frame - start, fps, config: CHIP });
    if (frame < start) return null;
    const size = Math.min(W, H) * st.s * (portrait ? 1.6 : 1);
    const wv = size * 0.8;
    const hv = size;
    // Laid out where the push leaves it; the parallax drift and the rise
    // there are a transform, since layout rounds a box to whole pixels and
    // a photo eased by `left`/`top` steps along.
    const parOf = (k: number) => (k - 1) * (st.far ? -0.6 : 1.4);
    const par = parOf(push);
    const parEnd = parOf(pushAt(Number.POSITIVE_INFINITY));
    const x = W * st.x + (W * st.x - W / 2) * parEnd;
    const y = H * st.y + (H * st.y - H / 2) * parEnd;
    const dx = (W * st.x - W / 2) * par - (W * st.x - W / 2) * parEnd;
    const dy =
      (H * st.y - H / 2) * par -
      (H * st.y - H / 2) * parEnd +
      (1 - Math.min(1, p)) * size * 0.25;
    const shift =
      Math.abs(dx) > 1e-3 || Math.abs(dy) > 1e-3
        ? `translate(${dx}px, ${dy}px) `
        : "";
    return (
      <div
        key={`sat-${i}`}
        style={{
          position: "absolute",
          left: x - wv / 2,
          top: y - hv / 2,
          width: wv,
          height: hv,
          borderRadius: wv * 0.06,
          overflow: "hidden",
          transform: `${shift}scale(${0.4 + 0.6 * p}) rotate(${st.r}deg)`,
          opacity: interpolate(p, [0, 0.35], [0, st.far ? 0.5 : 1], CLAMP),
          filter: st.far ? `blur(${6 * (Math.min(W, H) / 720)}px)` : undefined,
          boxShadow: st.far ? undefined : c.shadow,
          border: `1px solid ${c.border}`,
        }}
      >
        <Img
          src={img}
          style={{ width: "100%", height: "100%", objectFit: "cover" }}
        />
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        background: background === undefined ? bg : undefined,
        overflow: "hidden",
      }}
    >
      {background === undefined ? (
        <>
          <GshGround
            preset={preset}
            params={gParams}
            timeOffset={c.groundOffset}
            timeScale={0.5}
          />
          <AbsoluteFill
            style={{
              background: `radial-gradient(${portrait ? "90% 46%" : "62% 70%"} at 50% 50%, rgba(${c.scrim},${c.scrimAlpha}) 0%, rgba(${c.scrim},0) 100%)`,
            }}
          />
        </>
      ) : (
        <AbsoluteFill
          style={{
            background: background === "transparent" ? undefined : background,
          }}
        />
      )}
      <ScaleLayer scale={layerScale}>
        {sats.map((st, i) => renderSat(st, i, "far"))}
        <svg
          width={W}
          height={H}
          viewBox={`0 0 ${W} ${H}`}
          style={{
            position: "absolute",
            inset: 0,
            overflow: "visible",
            transform: glide(textTilt),
          }}
          aria-hidden
        >
          <g transform={`translate(${ox} ${oy}) scale(${scale})`}>
            {words.map((w, i) => renderWord(w, i))}
          </g>
        </svg>
        {sats.map((st, i) => renderSat(st, i, "near"))}
        <div
          style={{
            position: "absolute",
            left: tileTravels ? 0 : tileX,
            top: tileTravels ? 0 : tileY,
            width: tileW,
            height: tileH,
            borderRadius: Math.max(6, tileW * 0.07),
            overflow: "hidden",
            boxShadow: c.shadow,
            border: `1px solid ${c.border}`,
            transform: `${tileTravels ? `translate(${tileX}px, ${tileY}px) ` : ""}scale(${tileScale})`,
            filter: moveBlur > 0.3 ? `blur(${moveBlur * 0.35}px)` : undefined,
          }}
        >
          <Img
            src={tileSrc}
            style={{ width: "100%", height: "100%", objectFit: "cover" }}
          />
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

export default PhotoCaret;

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The photo tile hopping along the line like a caret, each word typing in as
// it leaves, the hops quickening; the far photos drifting in from the start,
// the near ones popping in after the accent word, and the slow push through
// the hold. Frames on the 30 fps scene timeline, after `delay` and `speed`.
// The ids are public: a saved `timing` prop refers to them.

export type PhotoCaretElementId =
  | "intro"
  | `word:${number}`
  | "push"
  | `far:${number}`
  | `near:${number}`;

export interface PhotoCaretTimingProps {
  text?: string;
  firstStep?: number;
  hold?: number;
}

export const DEFAULT_TEXT = "Your launch, / your name / on it.";
export const DEFAULT_FIRST_STEP = 12;

export const BEAT = {
  intro: 12,
  decay: 0.88,
  minStep: 6,
  breath: 9,
  reveal: 8,
  settle: 12,
  hold: 45,
};

/** The tile grows from the big photo into its slot over this many frames. */
const INTRO = 16;
/** A word fades in over `fade` while it types in over `reveal`. */
const FADE = 4;
/** The tile squashes on each hop, peaking at `squashPeak`. */
const SQUASH_PEAK = 3;
const SQUASH = 9;
/** The accent word takes its colour over this many frames. */
const ACCENT = 10;
/** The push eases in over the hold, short of its end by this much. */
const PUSH_SHORT = 12;
/** Far photos drift in every `FAR_GAP` from `FAR_AT`; near ones after the payoff. */
const FAR_AT = -2;
const FAR_GAP = 4;
const NEAR_AT = 2;
const NEAR_GAP = 3;
/** Both photo layouts have three near photos, then four far ones. */
const NEAR_COUNT = 3;
const FAR_COUNT = 4;

export const parseLines = (text: string) =>
  text
    .split("/")
    .map((l) => l.trim().split(/\s+/).filter(Boolean))
    .filter((l) => l.length > 0);

export const hopTimes = (count: number, firstStep: number) => {
  const out: number[] = [];
  let t = BEAT.intro;
  for (let k = 0; k < count; k++) {
    if (k === count - 1) t += BEAT.breath;
    out.push(t);
    const g = Math.max(
      BEAT.minStep,
      Math.round((firstStep * BEAT.decay ** k) / 3) * 3,
    );
    t += g;
  }
  return out;
};

// `intro` is the tile growing into place. `word:<i>` is the hop off word `i`
// with the word typing in, until the next hop; the words form a chain. The
// last one runs through the settle and carries the accent beat; `push`
// follows it. `far:<j>` and `near:<j>` are the photos, in their layout's
// order; the near ones follow the last word.
export const photoCaretTimeline = defineTimeline<
  PhotoCaretElementId,
  PhotoCaretTimingProps
>(
  ({
    text = DEFAULT_TEXT,
    firstStep = DEFAULT_FIRST_STEP,
    hold = BEAT.hold,
  }) => {
    const words = parseLines(text).flat();
    const n = words.length;
    const hops = hopTimes(n, firstStep);
    const payoff = hops[n - 1];
    const elements: TimelineElement<PhotoCaretElementId>[] = [
      {
        id: "intro",
        lane: "Tile",
        label: "intro",
        start: 0,
        length: INTRO,
      },
    ];
    for (let j = 0; j < FAR_COUNT; j++) {
      elements.push({
        id: `far:${j}`,
        lane: "Far photos",
        label: `far photo ${j + 1}`,
        start: j * FAR_GAP + FAR_AT,
        length: FAR_GAP,
        follows: j > 0 ? `far:${j - 1}` : undefined,
      });
    }
    words.forEach((word, k) => {
      const last = k === n - 1;
      elements.push({
        id: `word:${k}`,
        lane: "Words",
        label: word,
        start: hops[k],
        length: last ? BEAT.settle : hops[k + 1] - hops[k],
        follows: k > 0 ? `word:${k - 1}` : undefined,
        beats: {
          reveal: BEAT.reveal,
          fade: FADE,
          squashPeak: SQUASH_PEAK,
          squash: SQUASH,
          accent: ACCENT,
        },
      });
    });
    if (n > 0) {
      elements.push({
        id: "push",
        lane: "Camera",
        label: "push",
        start: payoff + BEAT.settle,
        length: hold - PUSH_SHORT,
        follows: `word:${n - 1}`,
      });
      for (let j = 0; j < NEAR_COUNT; j++) {
        elements.push({
          id: `near:${j}`,
          lane: "Near photos",
          label: `near photo ${j + 1}`,
          start: payoff + NEAR_AT + j * NEAR_GAP,
          length: NEAR_GAP,
          follows: j > 0 ? `near:${j - 1}` : `word:${n - 1}`,
        });
      }
    }
    return elements.sort((a, b) => a.start - b.start);
  },
);
